from __future__ import annotations

import re
from datetime import date

from fastapi.responses import HTMLResponse

from .web import dashboard_html


_OLD_CARD = '''<div class="card"><div class="section-title"><h2>💰 Surebet</h2></div><div class="surebet-buttons"><button onclick="loadSurebetPre()">📅 SUREBET PRE-PARTIDO</button><button class="live-button" onclick="loadSurebetLive()">🔴 SUREBET EN VIVO · BUSCAR AHORA</button></div><div class="status muted" id="surebet-status">El modo EN VIVO no consulta la API hasta que pulses el botón.</div><div id="surebet" class="muted">Selecciona PRE-PARTIDO o EN VIVO.</div></div>'''

_NEW_CARD = '''<div class="card"><div class="section-title"><h2>💰 Surebet</h2><p class="muted">Separación geográfica y temporal para no mezclar oportunidades.</p></div><div class="surebet-scope"><button id="scope-peru" onclick="setSurebetScope('peru')">🇵🇪 PERÚ</button><button id="scope-world" onclick="setSurebetScope('world')">🌎 MUNDIAL</button><button id="scope-all" onclick="setSurebetScope('all')">🌐 TODO</button></div><div class="surebet-buttons"><button id="surebet-pre-button" onclick="loadSurebetPre()">📅 SUREBET PRE-PARTIDO</button><button id="surebet-live-button" class="live-button" onclick="loadSurebetLive()">🔴 SUREBET LIVE · BUSCAR AHORA</button></div><div class="surebet-filters"><label>LIGA <select id="surebet-league" onchange="applyLeagueFilter()"><option value="">TODAS LAS LIGAS</option></select></label></div><div class="status muted" id="surebet-status">Elige PERÚ o MUNDIAL y luego LIVE o PRE-PARTIDO.</div><div id="surebet-summary" class="surebet-summary"></div><div id="surebet" class="muted">Aún no se ha realizado una búsqueda de surebets.</div></div>'''

_NEW_JS = '''const $=id=>document.getElementById(id),surebetBox=$('surebet'),surebetStatus=$('surebet-status'),surebetSummary=$('surebet-summary'),preButton=$('surebet-pre-button'),liveButton=$('surebet-live-button'),leagueSelect=$('surebet-league');let surebetScope='peru',lastSurebetData=null;function setSurebetScope(scope){surebetScope=scope;['peru','world','all'].forEach(x=>{const b=$('scope-'+x);if(b)b.classList.toggle('active',x===scope)});if(lastSurebetData)renderSurebet(lastSurebetData)}function setSurebetBusy(busy){preButton.disabled=busy;liveButton.disabled=busy;preButton.style.opacity=busy?.65:1;liveButton.style.opacity=busy?.65:1}function renderSurebetSummary(mode,count,extra=''){const scopeLabel=surebetScope==='peru'?'🇵🇪 PERÚ':surebetScope==='world'?'🌎 MUNDIAL':'🌐 TODO';surebetSummary.innerHTML=`<div class="metric">${scopeLabel}<b>${mode}</b></div><div class="metric">SUREBETS<b>${count}</b></div>${extra?`<div class="metric">${esc(extra)}</div>`:''}`}function updateLeagueOptions(d){const leagues=Array.isArray(d.leagues)?d.leagues:[];const current=leagueSelect.value;leagueSelect.innerHTML='<option value="">TODAS LAS LIGAS</option>'+leagues.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');if(leagues.includes(current))leagueSelect.value=current}function applyLeagueFilter(){if(lastSurebetData)renderSurebet(lastSurebetData)}function renderSurebet(d){lastSurebetData=d;updateLeagueOptions(d);let rows=Array.isArray(d.opportunities)?d.opportunities:[];const selectedLeague=leagueSelect.value;if(selectedLeague)rows=rows.filter(o=>(o.competition||'').toLowerCase().includes(selectedLeague.toLowerCase()));renderSurebetSummary(d.mode==='live'?'🔴 LIVE':'📅 PRE-MATCH',rows.length,d.refreshed_on_demand?'Cuotas actualizadas ahora':'Cuotas almacenadas');if(!rows.length){surebetBox.innerHTML='<p><strong>ℹ️ No hay surebets en este momento.</strong></p><p>La búsqueda respeta el ámbito seleccionado y la liga elegida.</p>';return}const groups={};rows.forEach(o=>(groups[o.competition||'Liga no identificada']??=[]).push(o));surebetBox.innerHTML=Object.entries(groups).map(([league,items])=>`<div class="surebet-league"><h3>🏆 ${esc(league)}</h3><table><thead><tr><th>Partido</th><th>Mercado</th><th>Línea</th><th>Resultado</th><th>Casa</th><th>Cuota</th><th>Margen</th><th>Acción</th></tr></thead><tbody>${items.flatMap(o=>Object.entries(o.outcomes||{}).map(([selection,q])=>`<tr><td>${esc(o.match)}</td><td>${esc(o.market)}</td><td>${esc(o.line??'-')}</td><td class="strong">${esc(selection)}</td><td>${esc(q.bookmaker)}</td><td>${q.odds}</td><td class="profit">${(o.profit_margin*100).toFixed(2)}%</td><td><button class="verify-button" onclick="verifySurebet(${o.match_id})">🔍 VERIFICAR</button></td></tr>`)).join('')}</tbody></table></div>`).join('')}async function readJsonResponse(response){let data={};try{data=await response.json()}catch(_){data={}}if(!response.ok)throw new Error(data.detail||`HTTP ${response.status}`);return data}async function loadSurebetPre(){setSurebetBusy(true);surebetStatus.textContent=`🔄 Revisando PRE-PARTIDO · ${surebetScope==='peru'?'PERÚ':surebetScope==='world'?'MUNDIAL':'TODO'}...`;surebetBox.innerHTML='<p>Buscando oportunidades pre-partido...</p>';surebetSummary.innerHTML='';try{const p=new URLSearchParams({limit:'100',scope:surebetScope});if(leagueSelect.value)p.set('league',leagueSelect.value);const d=await readJsonResponse(await fetch('/api/v1/arbitrage/pre-match?'+p.toString(),{cache:'no-store'}));surebetStatus.textContent=d.opportunities?.length?`✅ PRE-PARTIDO · ${d.opportunities.length} oportunidades.`:'ℹ️ PRE-PARTIDO revisado · NO HAY SUREBET EN ESTE MOMENTO.';renderSurebet(d)}catch(e){surebetStatus.textContent='❌ Error PRE-PARTIDO: '+e.message}finally{setSurebetBusy(false)}}async function loadSurebetLive(){setSurebetBusy(true);surebetStatus.textContent=`🔄 Actualizando LIVE · ${surebetScope==='peru'?'PERÚ':surebetScope==='world'?'MUNDIAL':'TODO'}...`;surebetBox.innerHTML='<p>Buscando oportunidades live...</p>';surebetSummary.innerHTML='';try{const p=new URLSearchParams({limit:'100',hours:'1',scope:surebetScope});if(leagueSelect.value)p.set('league',leagueSelect.value);const d=await readJsonResponse(await fetch('/api/v1/arbitrage/live?'+p.toString(),{method:'POST',cache:'no-store'}));const liveSeen=d.sync?.live_matches_seen??d.sync?.fixtures_saved??0,oddsSaved=d.sync?.odds_saved??0;surebetStatus.textContent=d.opportunities?.length?`🔴 LIVE · ${liveSeen} partidos · ${oddsSaved} cuotas · ${d.opportunities.length} surebets.`:`ℹ️ LIVE actualizado · ${liveSeen} partidos · ${oddsSaved} cuotas · NO HAY SUREBET EN ESTE MOMENTO.`;renderSurebet(d)}catch(e){surebetStatus.textContent='❌ Error EN VIVO: '+e.message}finally{setSurebetBusy(false)}}async function verifySurebet(matchId){surebetStatus.textContent='🔍 Verificando este partido...';try{const p=new URLSearchParams({limit:'100',scope:surebetScope});if(leagueSelect.value)p.set('league',leagueSelect.value);const d=await readJsonResponse(await fetch(`/api/v1/arbitrage/verify/${matchId}?`+p.toString(),{method:'POST',cache:'no-store'}));surebetStatus.textContent=d.surebet_confirmed?'✅ SUREBET CONFIRMADA después de verificar.':'⚠️ YA NO HAY SUREBET después de verificar.';renderSurebet(d)}catch(e){surebetStatus.textContent='❌ Error verificando: '+e.message}}setSurebetScope('peru');'''

# Match the complete surebet JS section in the base dashboard rather than relying
# on one exact historical string. This keeps the patch working as the dashboard
# gains unrelated scripts above or below the surebet functions.
_SUREBET_JS_RE = re.compile(r"function renderSurebet\(.*?async function loadFinal\(", re.S)


def dashboard_response(today: date) -> HTMLResponse:
    html = dashboard_html(today)
    html = html.replace(_OLD_CARD, _NEW_CARD)
    html = _SUREBET_JS_RE.sub(_NEW_JS + "async function loadFinal(", html, count=1)
    # Fallback for future dashboard changes where the exact card is no longer
    # present but the original buttons remain discoverable.
    html = html.replace('<button onclick="loadSurebetPre()">', '<button id="surebet-pre-button" onclick="loadSurebetPre()">', 1)
    html = html.replace('<button class="live-button" onclick="loadSurebetLive()">', '<button id="surebet-live-button" class="live-button" onclick="loadSurebetLive()">', 1)
    html = html.replace('.profit{font-weight:800}', '.profit{font-weight:800}.metric{background:#f4f6fa;border-radius:10px;padding:10px}.metric b{font-size:20px;display:block;margin-top:4px}.surebet-scope{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.surebet-scope button.active{font-weight:800;border:2px solid currentColor}.surebet-filters{margin:10px 0}.surebet-filters select{padding:8px;border-radius:8px}.surebet-league{margin-top:18px}')
    return HTMLResponse(html)
